int kvm_vm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	int ret;
	struct kvm_device_ops *ops;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_get_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	cd->fd = 0;

	mutex_lock(&kvm->lock);

	cd->dev = kzalloc(ops->dev_size, GFP_KERNEL);
	if (!cd->dev) {
		mutex_unlock(&kvm->lock);
		return -ENOMEM;
	}

	cd->dev->ops = ops;
	cd->dev->kvm = kvm;

	if (ops->init) {
		ret = ops->init(cd->dev);
		if (ret < 0) {
			kfree(cd->dev);
			mutex_unlock(&kvm->lock);
			return ret;
		}
	}

	if (ops->create) {
		ret = ops->create(cd->dev, cd->flags);
		if (ret < 0) {
			if (ops->destroy)
				ops->destroy(cd->dev);
			kfree(cd->dev);
			mutex_unlock(&kvm->lock);
			return ret;
		}
	}

	list_add(&cd->dev->list, &kvm->devices);

	mutex_unlock(&kvm->lock);

	return 0;
}

int kvm_dev_ioctl_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kvmalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = -EINVAL;

	list_for_each_entry(dev, &kvm->devices, list) {
		if (dev->ops == ops && dev->id == cd->id) {
			r = 0;
			goto unlock;
		}
	}

	dev->ops = ops;
	dev->kvm = kvm;
	dev->id = cd->id;
	dev->fd = get_unused_fd_flags(O_CLOEXEC);
	if (dev->fd < 0) {
		r = dev->fd;
		goto unlock;
	}

	r = ops->init(dev);
	if (r) {
		put_unused_fd(dev->fd);
		dev->fd = -1;
		goto unlock;
	}

	list_add(&dev->list, &kvm->devices);
	fd_install(dev->fd, kvm_device_fops(dev));

	cd->fd = dev->fd;
unlock:
	kvm_unlock(kvm);
	if (r)
		ops->destroy(dev);
	return r;
}

