{
	int r;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	bool test = cd->test;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_dev_hold(ops);
	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	r = -EEXIST;
	list_for_each_entry(dev, &kvm->devices, list)
		if (dev->id == cd->id)
			goto unlock_and_fail;

	dev->id = cd->id;
	list_add_tail(&dev->list, &kvm->devices);

	mutex_unlock(&kvm->lock);

	r = ops->init(dev);
	if (r)
		goto init_failed;

	cd->fd = get_ufd();
	if (cd->fd < 0) {
		r = cd->fd;
		goto init_failed;
	}

	if (test)
		return 0;

